From 69dd4d5e08788c7c4e063705233f22f5ef8199c4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 17:56:06 +0100
Subject: [PATCH] components/calendar: list the day's events in its tooltip

Hovering a day in the calendar only showed a tooltip for its holiday
label, so seeing what was on another day meant clicking it. The day's
tooltip now lists the titles of all its events, one per line.

BUG: 433669
---
 components/calendar/qml/DayDelegate.qml | 23 +++++++++++++++++++++--
 1 file changed, 21 insertions(+), 2 deletions(-)

diff --git a/components/calendar/qml/DayDelegate.qml b/components/calendar/qml/DayDelegate.qml
index 2070c055ed..644c888f8f 100644
--- a/components/calendar/qml/DayDelegate.qml
+++ b/components/calendar/qml/DayDelegate.qml
@@ -132,6 +132,25 @@ PlasmaComponents.AbstractButton {
         return result;
     }

+    readonly property bool showToolTip: Kirigami.Settings.isMobile ? pressed : hovered
+    // Only fetch the day's events while the tooltip can be shown
+    readonly property string toolTipText: {
+        if (!showToolTip) {
+            return "";
+        }
+        const lines = [];
+        if (dateMatchingPrecision === PlasmaCalendar.Calendar.MatchYearMonthAndDay && model.eventCount > 0) {
+            for (const event of dayModel.eventsForDate(thisDate)) {
+                lines.push(event.title);
+            }
+        }
+        const subLabel = model.subLabel || "";
+        if (subLabel && !lines.includes(subLabel)) {
+            lines.unshift(subLabel);
+        }
+        return lines.join("\n");
+    }
+
     Loader {
         anchors.fill: parent

@@ -224,8 +243,8 @@ PlasmaComponents.AbstractButton {
         // ColumnLayout makes scrolling too slow, so use anchors to position labels

         PlasmaComponents.ToolTip.delay: Kirigami.Units.toolTipDelay
-        PlasmaComponents.ToolTip.text: dayStyle.model.subLabel || ""
-        PlasmaComponents.ToolTip.visible: !!dayStyle.model.subLabel && (Kirigami.Settings.isMobile ? dayStyle.pressed : dayStyle.hovered)
+        PlasmaComponents.ToolTip.text: dayStyle.toolTipText
+        PlasmaComponents.ToolTip.visible: dayStyle.toolTipText.length > 0

         PlasmaComponents.Label {
             id: label
-- 
